// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface ISwapRouter02 {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params) external payable returns (uint256 amountOut);
}

interface INonfungiblePositionManager {
    struct MintParams {
        address token0;
        address token1;
        uint24 fee;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        address recipient;
        uint256 deadline;
    }

    struct IncreaseLiquidityParams {
        uint256 tokenId;
        uint256 amount0Desired;
        uint256 amount1Desired;
        uint256 amount0Min;
        uint256 amount1Min;
        uint256 deadline;
    }

    function mint(MintParams calldata params)
        external
        payable
        returns (uint256 tokenId, uint128 liquidity, uint256 amount0, uint256 amount1);

    function increaseLiquidity(IncreaseLiquidityParams calldata params)
        external
        payable
        returns (uint128 liquidity, uint256 amount0, uint256 amount1);
}

interface IERC721Receiver {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data)
        external
        returns (bytes4);
}

/// @title Rebalancer
/// @notice Rebalances a WETH-heavy purse and deploys it into a single tight
///         Uniswap v3 WETH/USDC 0.30% position bracketing the current tick.
contract Rebalancer is IERC721Receiver {
    address public constant WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address public constant USDC = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;
    ISwapRouter02 public constant ROUTER = ISwapRouter02(0x68b3465833fb72A70ecDF485E0e4C7bD8665Fc45);
    INonfungiblePositionManager public constant NPM =
        INonfungiblePositionManager(0xC36442b4a4522E871399CD717aBDD847Ab11FE88);

    // Target pool: USDC (token0) / WETH (token1), 0.30% fee, tick spacing 60.
    uint24 public constant POOL_FEE = 3000;
    // Swaps are routed through the deeper 0.05% pool so the target pool's
    // tick is not pushed around by our own rebalancing trade.
    uint24 public constant SWAP_FEE = 500;

    // Current tick 200808. Bounds are multiples of 60:
    //   lower 200640 -> 168 ticks below (~1.69% down)
    //   upper 201000 -> 192 ticks above (~1.94% up)
    int24 public constant TICK_LOWER = 200640;
    int24 public constant TICK_UPPER = 201000;

    // Reference price used for slippage floors (USDC per WETH).
    uint256 public constant REF_PRICE = 1900;

    // For this range at the current tick the position wants roughly
    // 46.7% of value in WETH and 53.3% in USDC. Starting from 50 WETH +
    // 5000 USDC (~100k USDC total), ~25.6 WETH must be sold for USDC.
    uint256 public constant WETH_TO_SELL = 25.6 ether;

    uint256 public tokenId;

    function provide() external {
        require(tokenId == 0, "already provided");

        IERC20(WETH).approve(address(ROUTER), type(uint256).max);
        IERC20(USDC).approve(address(ROUTER), type(uint256).max);
        IERC20(WETH).approve(address(NPM), type(uint256).max);
        IERC20(USDC).approve(address(NPM), type(uint256).max);

        // 1. Rebalance: sell WETH for USDC so the purse matches the range ratio.
        _swapWethForUsdc(WETH_TO_SELL);

        // 2. Mint the position with everything we hold.
        (uint256 id,,,) = NPM.mint(
            INonfungiblePositionManager.MintParams({
                token0: USDC,
                token1: WETH,
                fee: POOL_FEE,
                tickLower: TICK_LOWER,
                tickUpper: TICK_UPPER,
                amount0Desired: IERC20(USDC).balanceOf(address(this)),
                amount1Desired: IERC20(WETH).balanceOf(address(this)),
                amount0Min: 0,
                amount1Min: 0,
                recipient: address(this),
                deadline: block.timestamp
            })
        );
        tokenId = id;

        // 3. Refinement: whatever was handed back, split it and top up the
        //    same position so it ends up holding nearly the whole purse.
        uint256 wethLeft = IERC20(WETH).balanceOf(address(this));
        uint256 usdcLeft = IERC20(USDC).balanceOf(address(this));

        if (wethLeft > 0.02 ether) {
            _swapWethForUsdc(wethLeft / 2);
        } else if (usdcLeft > 50e6) {
            _swapUsdcForWeth(usdcLeft / 2);
        } else {
            return;
        }

        NPM.increaseLiquidity(
            INonfungiblePositionManager.IncreaseLiquidityParams({
                tokenId: id,
                amount0Desired: IERC20(USDC).balanceOf(address(this)),
                amount1Desired: IERC20(WETH).balanceOf(address(this)),
                amount0Min: 0,
                amount1Min: 0,
                deadline: block.timestamp
            })
        );
    }

    function _swapWethForUsdc(uint256 amountIn) internal {
        // Floor: 5% below the reference price. WETH 1e18 -> USDC 1e6.
        uint256 minOut = (amountIn * REF_PRICE * 95) / 100 / 1e12;
        ROUTER.exactInputSingle(
            ISwapRouter02.ExactInputSingleParams({
                tokenIn: WETH,
                tokenOut: USDC,
                fee: SWAP_FEE,
                recipient: address(this),
                amountIn: amountIn,
                amountOutMinimum: minOut,
                sqrtPriceLimitX96: 0
            })
        );
    }

    function _swapUsdcForWeth(uint256 amountIn) internal {
        // Floor: 5% below the reference price. USDC 1e6 -> WETH 1e18.
        uint256 minOut = (amountIn * 1e12 * 95) / 100 / REF_PRICE;
        ROUTER.exactInputSingle(
            ISwapRouter02.ExactInputSingleParams({
                tokenIn: USDC,
                tokenOut: WETH,
                fee: SWAP_FEE,
                recipient: address(this),
                amountIn: amountIn,
                amountOutMinimum: minOut,
                sqrtPriceLimitX96: 0
            })
        );
    }

    function onERC721Received(address, address, uint256, bytes calldata) external pure override returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }
}
